def fitG(k,p=1.0):
    G=1-np.exp(-k*t**p)
    cols=[np.ones_like(t),G,G*P,G*P**2,P,P**2,P*t,P**2*t,t,P*G*t]
    X=np.column_stack(cols)
    c=np.linalg.lstsq(X,dP_dt,rcond=None)[0]
    return np.mean((dP_dt-X@c)**2)/np.var(dP_dt), c
best=None
for k in np.linspace(0.05,3,60):
