def buildG(a,extra):
    G=np.tanh(a*t)
    cols={'G':G,'GP':G*P,'GP2':G*P**2,'GP3':G*P**3,'1':np.ones_like(t),'P':P,'P2':P**2,'P3':P**3,'Pt':P*t,'P2t':P**2*t,'t':t,
          'Gt':G*t,'GPt':G*P*t,'GP2t':G*P**2*t,'Pt2':P*t**2,'P2t2':P**2*t**2,'t2':t**2}
    names=['G','GP','GP2','GP3','1','P','P2','P3','Pt','P2t','t']+extra
    X=np.column_stack([cols[n] for n in names])
    cc=np.linalg.lstsq(X,dP_dt,rcond=None)[0]
    return np.mean((dP_dt-X@cc)**2)/np.var(dP_dt), dict(zip(names,np.round(cc,4)))
